import com.google.gson.*;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import salve.core.embeddings.E5Tokenizer;
import salve.core.embeddings.E5EmbeddingEngine;
import salve.core.mind.EmbeddingCalibration;
import salve.core.memory.MemoryVectorStore;

/** Executes the production Java/JNI classes; expectations are generated by Hugging Face, not Salve. */
public final class VerifyE5 {
    public static void main(String[] args) throws Exception {
        JsonObject fixtures = JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();
        int count = 0;
        try (E5Tokenizer tokenizer = new E5Tokenizer(new File(args[0]))) {
            for (JsonElement value : fixtures.getAsJsonArray("cases")) {
                JsonObject row = value.getAsJsonObject();
                int[] expected = new Gson().fromJson(row.get("ids"), int[].class);
                int[] actual = tokenizer.encode(row.get("text").getAsString(), row.get("max_tokens").getAsInt());
                if (!Arrays.equals(expected, actual)) throw new AssertionError("Token case " + count
                        + " text=" + row.get("text") + "\nexpected=" + Arrays.toString(expected) + "\nactual=" + Arrays.toString(actual));
                count++;
            }
            if (!Arrays.equals(new int[]{0, 2}, tokenizer.encode("query: hola", 2)))
                throw new AssertionError("BOS/EOS must survive a two-token budget");
        }
        System.out.println("Tokenizer parity: " + count + "/" + count);
        if (args.length > 2) {
            JsonArray rows = JsonParser.parseString(Files.readString(Path.of(args[3]))).getAsJsonArray();
            try (E5EmbeddingEngine engine = new E5EmbeddingEngine(new File(args[2]), new File(args[0]))) {
                double maxError = 0;
                for (JsonElement value : rows) {
                    JsonObject row = value.getAsJsonObject();
                    float[] actual = row.get("kind").getAsString().equals("passage")
                            ? engine.passage(row.get("text").getAsString()) : engine.query(row.get("text").getAsString());
                    float[] expected = new Gson().fromJson(row.get("vector"), float[].class);
                    if (actual.length != 384 || expected.length != actual.length) throw new AssertionError("Wrong dimension");
                    for (int i = 0; i < expected.length; i++) {
                        if (!Float.isFinite(actual[i]) || !Float.isFinite(expected[i])) throw new AssertionError("Non-finite embedding");
                        maxError = Math.max(maxError, Math.abs(actual[i] - expected[i]));
                    }
                }
                // Dynamic INT8 can differ by backend round-off; catch wrong ids, mask, prefixes or pooling.
                if (maxError > 2e-4) throw new AssertionError("Embedding parity failed: " + maxError);
                System.out.println("Production Java ONNX parity: " + rows.size() + " vectors; max absolute error=" + maxError);
                EmbeddingCalibration.Result retrieval = EmbeddingCalibration.run(engine::query, engine::passage);
                EmbeddingCalibration.Result similarity = EmbeddingCalibration.run(engine::query);
                System.out.println("Retrieval: " + retrieval.describe() + " threshold=" + retrieval.threshold);
                System.out.println("Symmetric similarity: " + similarity.describe());
                if (!retrieval.passed || !similarity.passed) throw new AssertionError("Spanish calibration failed");
                MemoryVectorStore store = new MemoryVectorStore();
                int passages = 0;
                for (JsonElement value : rows) {
                    JsonObject row = value.getAsJsonObject();
                    if (row.get("kind").getAsString().equals("passage"))
                        store.put(passages++, engine.passage(row.get("text").getAsString()));
                }
                // Exercise the real persisted INT8 vector index, not just floating-point dot products.
                Path temporary = Files.createTempFile("salve-e5-index", ".bin");
                try { store.save(temporary.toFile()); store = MemoryVectorStore.load(temporary.toFile()); }
                finally { Files.deleteIfExists(temporary); }
                int queries = 0, first = 0, top3 = 0, oldCutoff = 0;
                for (JsonElement value : rows) {
                    JsonObject row = value.getAsJsonObject();
                    if (!row.get("kind").getAsString().equals("query")) continue;
                    float[] query = engine.query(row.get("text").getAsString());
                    java.util.List<MemoryVectorStore.Hit> hits = store.candidates(query, 3);
                    if (!hits.isEmpty() && hits.get(0).id == queries) first++;
                    for (MemoryVectorStore.Hit hit : hits) if (hit.id == queries) top3++;
                    for (MemoryVectorStore.Hit hit : store.nearest(query, 3, retrieval.threshold)) if (hit.id == queries) oldCutoff++;
                    queries++;
                }
                System.out.println("Persisted index: top1=" + first + "/" + queries + ", top3=" + top3
                        + "/" + queries + "; old calibration cutoff retained=" + oldCutoff);
                if (queries != 32 || passages != 32 || first < 25 || top3 < 28)
                    throw new AssertionError("Fixed Spanish retrieval corpus regressed");
            }
        }
    }
}
